	ERR_FAIL_NULL(tile_data);

	Color grid_color = EDITOR_GET("editors/tiles_editor/grid_color");
	Color selection_color = Color::from_hsv(Math::fposmod(grid_color.get_h() + 0.5, 1.0), grid_color.get_s(), grid_color.get_v(), 1.0);
